import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"

export function CreatePostForm() {
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Check if both fields have content to enable the publish button
  const isFormValid = title.trim() !== "" && content.trim() !== ""

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!isFormValid) return

    setIsSubmitting(true)

    try {
      // Here you would typically make an API call to create the post
      console.log("Creating post:", { title, content })

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000))

      // Reset form after successful submission
      setTitle("")
      setContent("")

      alert("Post published successfully!")
    } catch (error) {
      console.error("Error creating post:", error)
      alert("Failed to publish post. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <label htmlFor="title" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            Title
          </label>
          <Input
            id="title"
            type="text"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full"
          />
          <p className="text-xs text-muted-foreground">
            {title.length === 0 && "Title is required"}
          </p>
        </div>

        <div className="space-y-2">
          <label htmlFor="content" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            Content
          </label>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="min-h-[200px] w-full resize-none"
          />
          <p className="text-xs text-muted-foreground">
            {content.length === 0 && "Content is required"}
          </p>
        </div>

        <div className="flex items-center justify-between pt-4 border-t">
          <div className="text-sm text-muted-foreground">
            {isFormValid ? (
              <span className="text-green-600">Ready to publish</span>
            ) : (
              <span>Fill in both fields to enable publishing</span>
            )}
          </div>
          <Button
            type="submit"
            disabled={!isFormValid || isSubmitting}
            className="min-w-[100px]"
          >
            {isSubmitting ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                Publishing...
              </>
            ) : (
              "Publish"
            )}
          </Button>
        </div>
      </form>

      {/* Form status display */}
      <div className="p-4 bg-muted rounded-lg">
        <h3 className="text-sm font-medium mb-2">Form Status</h3>
        <div className="space-y-1 text-xs">
          <p>Title: {title.trim() === "" ? "❌ Empty" : "✅ Filled"}</p>
          <p>Content: {content.trim() === "" ? "❌ Empty" : "✅ Filled"}</p>
          <p>Publish Button: {isFormValid ? "✅ Enabled" : "❌ Disabled"}</p>
        </div>
      </div>
    </div>
  )
}

